import java.util.Scanner;

public class Main {
    static final int LOW_BYTE = 0b1111_1111;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        String bits = sc.next();

        System.out.printf("a: %d %s%n", a, bin8(a));
        System.out.printf("b: %d %s%n", b, bin8(b));
        System.out.printf("a & b: %d %s%n", a & b, bin8(a & b));
        System.out.printf("a | b: %d %s%n", a | b, bin8(a | b));
        System.out.printf("a ^ b: %d %s%n", a ^ b, bin8(a ^ b));
        int notA = ~a & LOW_BYTE;
        System.out.printf("~a low 8 bits: %d %s%n", notA, bin8(notA));
        System.out.println("a odd: " + ((a & 1) == 1));
        System.out.println("b odd: " + ((b & 1) == 1));
        System.out.println(bits + " = " + Integer.parseInt(bits, 2));
    }

    static String bin8(int x) {
        return String.format("%8s", Integer.toBinaryString(x)).replace(' ', '0');
    }
}

