    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            int k = sc.nextInt();
            String match = (n >> k) == n / (1 << k) ? "same" : "different";
            System.out.printf("n=%d k=%d: << %d, >> %d, >>> %d, %s%n",
                    n, k, n << k, n >> k, n >>> k, match);
        }
    }
}

