import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int mask = sc.nextInt();
        int i = sc.nextInt();

        boolean isSet = ((mask >> i) & 1) == 1;
        int set = mask | (1 << i);
        int cleared = mask & ~(1 << i);
        int toggled = mask ^ (1 << i);

        System.out.printf("mask: %d %s%n", mask, bin8(mask));
        System.out.printf("bit %d set: %b%n", i, isSet);
        System.out.printf("set: %d %s%n", set, bin8(set));
        System.out.printf("clear: %d %s%n", cleared, bin8(cleared));
        System.out.printf("toggle: %d %s%n", toggled, bin8(toggled));
    }

    static String bin8(int x) {
        return String.format("%8s", Integer.toBinaryString(x)).replace(' ', '0');
    }
}

