import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int odd = 0;
        while (sc.hasNextInt()) {
            int x = sc.nextInt();
            boolean power = x > 0 && (x & (x - 1)) == 0;
            System.out.printf("%d: power of two %b, bits %d%n", x, power, Integer.bitCount(x));
            odd ^= x;
        }
        System.out.println("odd one out: " + odd);
    }
}

