import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int powers = 0;
        int ones = 0;
        int odd = 0;
        while (sc.hasNextInt()) {
            int x = sc.nextInt();
            if (x > 0 && (x & (x - 1)) == 0) {
                powers++;
            }
            ones += Integer.bitCount(x);
            odd ^= x;
        }
        System.out.println("powers of two: " + powers);
        System.out.println("one bits: " + ones);
        System.out.println("odd one out: " + odd);
    }
}
